// Triplet representation of sparse matrix\nconst matrixA = [
  [0, 0, 5],  // row, col, value
  [1, 2, 3],
  [2, 1, 7]
];
\nconst matrixB = [
  [0, 0, 2],
  [1, 2, 4],
  [2, 1, 6]
];
\n// Add two sparse matrices\nfunction addSparseMatrices(A, B) {
  const result = [];
  let i = 0, j = 0;

  while (i < A.length && j < B.length) {
    if (A[i][0] < B[j][0]) {
      result.push(A[i]);
      i++;
    } else if (A[i][0] > B[j][0]) {
      result.push(B[j]);
      j++;
    } else {
      if (A[i][1] < B[j][1]) {
        result.push(A[i]);
        i++;
      } else if (A[i][1] > B[j][1]) {
        result.push(B[j]);
        j++;
      } else {
        result.push([A[i][0], A[i][1], A[i][2] + B[j][2]]);
        i++;
        j++;
      }
    }
  }

  // Copy remaining elements from A
  while (i < A.length) {
    result.push(A[i]);
    i++;
  }

  // Copy remaining elements from B
  while (j < B.length) {
    result.push(B[j]);
    j++;
  }

  return result;
}
\nconst result = addSparseMatrices(matrixA, matrixB);\nconsole.log('Result:', result); // [[0,0,7],[1,2,7],[2,1,13]]

// Linked list node for sparse matrix\nclass SparseMatrixNode {
  constructor(row, col, value) {
    this.row = row;
    this.col = col;
    this.value = value;
    this.next = null;
  }
}
